	    SELECT
	        'INFO'||
	        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(INTERVIEW_INFORMATION_NO), LENGTH('INFO' ) + 1)), 0) + 1, 6, '0')
	    FROM INTERVIEW_INFORMATION


    INSERT INTO INTERVIEW_INFORMATION (
		INTERVIEW_INFORMATION_NO
